from decimal import Decimal

def calc(m, n):
    if n > 10:
        c = Decimal('5') * Decimal('1.16')
    else:
        c = Decimal('0')
    total = round(Decimal(str(m)) + c, 2)
    if total == Decimal('15.80'):
        print("caso especial")
    return total

